/* ======================= PROCESSES ======================= */
const SIG_TABLE = `<table><tr><th>#</th><th>Name</th><th>Default</th><th>Meaning</th></tr><tr><td>1</td><td>SIGHUP</td><td>terminate</td><td>terminal closed; daemons often reload config</td></tr><tr><td>2</td><td>SIGINT</td><td>terminate</td><td>Ctrl+C</td></tr><tr><td>3</td><td>SIGQUIT</td><td>core dump</td><td>Ctrl+\\</td></tr><tr><td>9</td><td>SIGKILL</td><td>terminate</td><td>cannot be caught, blocked or ignored</td></tr><tr><td>15</td><td>SIGTERM</td><td>terminate</td><td>polite request to exit (default of kill)</td></tr><tr><td>17</td><td>SIGCHLD</td><td>ignore</td><td>a child stopped or exited</td></tr><tr><td>18</td><td>SIGCONT</td><td>continue</td><td>resume a stopped process</td></tr><tr><td>19</td><td>SIGSTOP</td><td>stop</td><td>pause; cannot be caught</td></tr><tr><td>20</td><td>SIGTSTP</td><td>stop</td><td>Ctrl+Z</td></tr><tr><td>10/12</td><td>SIGUSR1/2</td><td>terminate</td><td>user-defined (e.g. reopen logs)</td></tr></table>`;
lesson('ps', {
  n: 'ps', s: 'Shows a snapshot of running processes: PID, owner, CPU/memory use, state and command.',
  an: 'A photo of everyone currently at work in a factory, with their badge numbers and what they are doing — taken at one instant.',
  nm: '<b>p</b>rocess <b>s</b>tatus.',
  sx: 'ps [OPTIONS]', p: [['ps', 'cmd', 'The command.', true], ['[OPTIONS]', 'opt', 'BSD style without dash (aux) or UNIX style with dash (-ef). -o picks columns.', false]],
  ex1: 'ps aux',
  sc: [['openat /proc', 'opens the /proc directory', 'openat(AT_FDCWD, "/proc", O_RDONLY|O_DIRECTORY) = 3'], ['getdents64', 'lists the numbered sub-directories — one per process', 'getdents64(3, /* 412 entries */, 32768) = 10216'], ['openat + read (×N)', 'reads /proc/PID/stat, status and cmdline for every process', 'read(4, "520 (nginx) S 1 520 520 0 -1 …", 1024) = 312'], ['write', 'prints the table', 'write(1, "USER  PID %CPU %MEM …", 4096) = 4096']],
  ch: 'Nothing — read only.', out: 'A table: <code>USER PID %CPU %MEM VSZ RSS TTY STAT START TIME COMMAND</code> (for aux).', ec: '0.',
  f: [['aux', '', 'All processes of all users, user-oriented columns (BSD style, no dash).', 'ps aux', true], ['-ef', '', 'All processes, full format with PPID (UNIX style).', 'ps -ef', true], ['-e', '', 'Every process.', 'ps -e', false], ['-u USER', '', 'Processes of one user.', 'ps -u user', false], ['-o COLS', '', 'Choose columns: pid,ppid,ni,stat,comm…', 'ps -eo pid,ni,comm', true], ['--sort', '', 'Sort, e.g. --sort=-%mem.', 'ps aux --sort=-%cpu', false], ['-p PID', '', 'One specific process.', 'ps -p 520', false], ['f / --forest', '', 'Show parent/child tree.', 'ps auxf', false]],
  e: [['ps', '    PID TTY          TIME CMD\n   1200 pts/0    00:00:00 bash', 'Only processes of this terminal.'], ['ps aux', 'USER   PID %CPU %MEM … COMMAND', 'Everything, with CPU and memory.'], ['ps -ef | head -5', 'UID  PID  PPID  C STIME TTY TIME CMD', 'Shows parent PIDs.'], ['ps aux | grep python', '', 'Find processes by name.'], ['ps -eo pid,ni,stat,comm', '', 'Custom columns: nice value and state.'], ['ps aux --sort=-%cpu | head -3', '', 'Top CPU users.']],
  u: `<p>A <b>process</b> is a running program with a unique <b>PID</b>. Every process except PID 1 has a parent (<b>PPID</b>); your commands are children of your shell (PID 1200 here). PID 1 (systemd) is the ancestor of everything.</p><p><b>STAT column:</b> R running/runnable · S sleeping (waiting for something) · D uninterruptible disk wait · T stopped · Z zombie. Extra flags: s session leader, + foreground, &lt; high priority, N low priority.</p><p><b>Zombies</b> (Z) have finished but their parent hasn't collected the exit status yet (wait()). They use no CPU or memory — only a table slot. <b>Orphans</b> are processes whose parent died; PID 1 adopts them.</p><p>VSZ = virtual memory size (all mapped memory), RSS = resident set size (actually in RAM), both in KiB.</p>`,
  adv: `<p>ps is a pure /proc reader (procps-ng). Fields map to <code>/proc/PID/stat</code> (state, ppid, utime, stime, nice, starttime…), <code>/proc/PID/status</code> (VmRSS, Uid), <code>/proc/PID/cmdline</code> (NUL-separated argv). Kernel side, each is a <code>task_struct</code>; %CPU = cumulative CPU time / elapsed time since start (not instantaneous — use top for that). Kernel threads show in [brackets] because they have no cmdline.</p>`,
  mi: [['ps', 'Shows only your terminal\'s processes — the server process you\'re looking for is missing.', 'ps aux'], ['ps -aux', 'Mixes styles; works with a warning on some systems.', 'ps aux'], ['ps aux | grep nginx (counting the grep line)', 'The grep itself appears in the list.', 'pgrep -a nginx']],
  safe: 'ps is read-only.',
  r: [['top', 'Live, refreshing view; ps is a one-time snapshot.'], ['kill', 'Act on a PID you found with ps.'], ['proc', '/proc is where ps gets its data.'], ['pgrep', 'pgrep/pkill find processes by name directly.']],
  cs: ['<code>ps aux</code> everything · <code>ps -ef</code> with PPID', 'STAT: R run · S sleep · T stopped · Z zombie', '<code>ps -eo pid,ni,comm</code> custom columns', '<code>ps aux --sort=-%mem | head</code>', 'Data comes from /proc'],
  q: [['What does state Z mean?', ['Zero CPU', 'Zombie: finished, waiting for its parent to collect the status', 'Zipped', 'Frozen'], 1, 'Its parent hasn\'t called wait().'], ['Where does ps get its information?', ['A log file', '/proc', 'The disk', 'systemd'], 1, '/proc is a virtual filesystem.'], ['Which shows parent PIDs?', ['ps', 'ps -ef', 'ps -p', 'ps x'], 1, '-ef includes the PPID column.']],
  c: { t: 'List <b>all</b> processes of all users (find the stuck <code>python3</code>, PID 777).', try: 'ps aux', chk: ctx => okRun(ctx, 'ps') && outOf(ctx).includes('777') },
});
lesson('top', {
  n: 'top', s: 'Live, auto-refreshing view of processes sorted by CPU usage, plus system load and memory.',
  an: 'A live scoreboard at a race: positions change every few seconds, the leader (biggest CPU user) at the top.',
  nm: '<b>top</b> — shows the top resource consumers.',
  sx: 'top [-b] [-n N] [-u USER] [-p PID]', p: [['top', 'cmd', 'Interactive program.', true], ['[OPTIONS]', 'opt', '-b batch mode (for scripts), -n iterations, -u user, -p PID.', false]],
  ex1: 'top',
  sc: [['openat/read /proc/stat', 'reads overall CPU counters', 'read(3, "cpu  10132153 290696 3084719 …", 8192) = 2310'], ['read /proc/meminfo, /proc/loadavg', 'memory and load average', 'read(4, "MemTotal: 8041512 kB…", 2048) = 1452'], ['read /proc/PID/stat (×N)', 'per-process CPU time; the DIFFERENCE between two refreshes gives %CPU', 'read(5, "777 (python3) R …", 1024) = 302'], ['nanosleep / poll', 'waits 3 s (or for a key press), then repeats', 'pselect6(1, [0], NULL, NULL, {tv_sec=3}, NULL) = 0']],
  ch: 'Nothing (unless you use k to kill or r to renice from inside).', out: 'A full-screen table refreshed every 3 seconds (the simulator prints one snapshot).', ec: '0.',
  f: [['-b', '', 'Batch mode: plain text, good for logs/pipes.', 'top -b -n 1 | head', true], ['-n N', '', 'Exit after N refreshes.', 'top -n 1', true], ['-u USER', '', 'Only one user\'s processes.', 'top -u user', false], ['-p PID', '', 'Watch specific PIDs.', 'top -p 777', false], ['-d SECS', '', 'Refresh delay.', 'top -d 1', false], ['P / M / q', '', 'Inside top: sort by CPU / memory, quit.', 'M', true], ['k / r', '', 'Inside top: kill / renice a PID.', 'k', false]],
  e: [['top', 'top - 09:34:12 up 4:15, 1 user, load average: 0.42…', 'Live view (q to quit).'], ['top -b -n 1 | head -12', '', 'One snapshot as text.'], ['top -u user', '', 'Only your processes.'], ['htop', '', 'A friendlier alternative (sudo apt install htop).'], ['uptime', '… load average: 0.42, 0.37, 0.31', 'Just the load line.']],
  u: `<p><b>Header lines:</b> uptime & <b>load average</b> (runnable + waiting tasks averaged over 1, 5, 15 min — compare with your number of CPU cores), task counts by state, CPU split (<b>us</b> user, <b>sy</b> kernel, <b>ni</b> niced, <b>id</b> idle, <b>wa</b> waiting for disk), then memory and swap.</p><p><b>Columns:</b> PR/NI priority & nice, VIRT/RES memory, S state, %CPU (can exceed 100% on multi-core), TIME+ total CPU used. Here <code>python3 stuck_app.py</code> (PID 777) is hogging CPU.</p>`,
  adv: `<p>%CPU is computed as Δ(utime+stime) of the task divided by Δ(total jiffies) between refreshes. Load average comes from the kernel's exponentially-decayed counter of tasks in R and D states (<code>/proc/loadavg</code>) — D-state tasks waiting on slow I/O raise load without using CPU.</p>`,
  mi: [['Leaving top running in a script', 'It never exits and floods output.', 'top -b -n 1'], ['Reading high load as “CPU busy”', 'Load also counts tasks stuck waiting on disk (D state).', 'Check %wa and ps state D'], ['Pressing Ctrl+C to “refresh”', 'That quits top.', 'top refreshes by itself; Space forces a refresh']],
  safe: 'Viewing is harmless; the k key inside top can kill processes.',
  r: [['ps', 'One snapshot, scriptable.'], ['kill', 'Stop the hog you found.'], ['nice', 'Lower a process\'s priority instead of killing it.'], ['free', 'Memory overview only.']],
  cs: ['<code>top</code> live view · <b>q</b> quit', '<b>P</b> sort by CPU · <b>M</b> by memory', 'load average vs number of cores', '<code>top -b -n 1</code> one snapshot', '<code>htop</code> = nicer UI'],
  q: [['What does load average 4.0 mean on a 4-core machine?', ['Overloaded ×4', 'Roughly fully used', 'Idle', '4% CPU'], 1, 'About one runnable task per core.'], ['Which key sorts by memory inside top?', ['M', 'P', 'K', 'S'], 0, 'M = memory, P = CPU.'], ['How to run top non-interactively once?', ['top -1', 'top -b -n 1', 'top --once', 'top -q'], 1, 'Batch mode, one iteration.']],
  c: { t: 'Open <code>top</code> and identify the process using the most CPU.', try: 'top', chk: ctx => okRun(ctx, 'top') || okRun(ctx, 'htop') },
});
lesson('kill', {
  n: 'kill', s: 'Sends a signal to a process — usually to ask it (or force it) to stop.',
  an: 'SIGTERM is knocking on the door: “please finish up and leave” — the guest packs their bags. SIGKILL is security physically removing them mid-sentence — nothing gets packed.',
  nm: '<b>kill</b> — although it can send any signal (pause, resume, reload), not just death.',
  sx: 'kill [-SIGNAL] PID|%JOB...   |   kill -l', p: [['kill', 'cmd', 'Bash builtin (also /usr/bin/kill).', true], ['[-SIGNAL]', 'opt', 'Signal name or number: -TERM (default, 15), -KILL (9), -HUP (1), -STOP, -CONT.', false], ['PID|%JOB...', 'arg', 'Process IDs (from ps) or job numbers (%1 from jobs).', true]],
  ex1: 'kill 777',
  sc: [['kill', 'asks the kernel to deliver signal 15 to PID 777 (permission: same UID or root)', 'kill(777, SIGTERM) = 0'], ['(in the target)', 'if it has a handler, it runs (cleanup, then exit); if it ignores the signal, nothing happens; default action = terminate', ''], ['wait (parent)', 'the parent collects the exit status (“Terminated”, 128+15 = 143)', 'wait4(777, [{WIFSIGNALED(s) && WTERMSIG(s) == SIGTERM}], …)']],
  ch: 'The target process may exit (removed from the process table), stop, continue, or reload — depending on the signal and the program.', out: 'Nothing on success. For jobs, the shell later prints e.g. <code>[1]+ Terminated sleep 100</code>.', ec: '0 = signal delivered (not necessarily obeyed!), 1 = no such process / not permitted.',
  f: [['-15 / -TERM', '', 'Polite stop (default). Program can clean up.', 'kill 777', true], ['-9 / -KILL', '', 'Immediate, unconditional kill.', 'kill -9 777', true], ['-1 / -HUP', '', 'Hang-up; many daemons reload config.', 'kill -HUP 520', true], ['-STOP / -CONT', '', 'Pause / resume.', 'kill -STOP 888', false], ['-2 / -INT', '', 'Same as Ctrl+C.', 'kill -INT 888', false], ['-l', '', 'List signal names and numbers.', 'kill -l', true], ['%N', '', 'Target a shell job instead of a PID.', 'kill %1', true]],
  e: [['kill -l', ' 1) SIGHUP\n 2) SIGINT …', 'All signals.'], ['kill 777', '', 'SIGTERM to the stuck app — it IGNORES it (see the animation).'], ['kill -9 777', '', 'SIGKILL can\'t be ignored: gone.'], ['sleep 300 & kill %1', '[1] 2190\n[1]+ Terminated sleep 300', 'Kill a background job by job number.'], ['kill 1', 'bash: kill: (1) - Operation not permitted', 'You can only signal your own processes.'], ['pkill -f server.py', '', 'Kill by name instead of PID.']],
  u: `<p><b>Signals</b> are small numbered messages the kernel delivers to a process. A program can <i>catch</i> most signals with a handler (e.g. to save work on SIGTERM), <i>ignore</i> them, or accept the <i>default</i> action. Two can never be caught or ignored: <b>SIGKILL (9)</b> and <b>SIGSTOP (19)</b>.</p><p><b>Always try SIGTERM first</b>, wait a few seconds, and only then use -9. SIGKILL gives the program no chance to flush buffers, remove lock/temp files or close network connections cleanly — you may get corrupted data.</p>${SIG_TABLE}<p>A process killed by signal N exits with status 128+N (130 for Ctrl+C, 137 for kill -9, 143 for TERM).</p>`,
  adv: `<p><code>kill(2)</code> → <code>group_send_sig_info()</code>: the kernel checks permission (same real/effective UID or CAP_KILL), sets the bit in the target's pending mask and wakes it. The signal is handled when the target next returns to user space; SIGKILL wakes even interruptible sleeps but not uninterruptible D-state (a process stuck in D can't be killed until the I/O completes). PID 1 only receives signals it has handlers for — that's why <code>kill -9 1</code> does nothing.</p>`,
  mi: [['kill -9 everything immediately', 'No cleanup: half-written files, stale lock files, broken DB state.', 'kill PID; sleep 5; kill -9 PID only if still running'], ['kill python', '“arguments must be process or job IDs”.', 'pkill python   # or kill $(pgrep python)'], ['kill a zombie (Z)', 'Nothing happens — it is already dead.', 'Kill or fix its PARENT so it reaps the child']],
  w: '<b>kill -9</b> skips all cleanup and can corrupt data (databases, files being written). Killing the wrong PID (e.g. sshd, your session, PID reused after a restart) can lock you out or crash services. Always confirm the PID with <code>ps -p PID</code> right before killing, and prefer SIGTERM.',
  r: [['signals', 'All signals explained in depth.'], ['ps', 'Find the PID first.'], ['jobs', 'kill %N for jobs started from this shell.'], ['pkill', 'pkill / killall select processes by NAME (pkill matches partial names; killall exact).']],
  cs: ['<code>kill PID</code> = SIGTERM (polite)', '<code>kill -9 PID</code> = SIGKILL (last resort)', '<code>kill -l</code> list signals', '<code>kill %1</code> kill job 1', 'Only your own processes unless root'],
  q: [['Which signal cannot be caught or ignored?', ['SIGTERM', 'SIGHUP', 'SIGKILL', 'SIGINT'], 2, 'SIGKILL (and SIGSTOP).'], ['Default signal sent by kill PID?', ['9', '15', '1', '2'], 1, 'SIGTERM = 15.'], ['Why prefer SIGTERM over SIGKILL?', ['It\'s faster', 'The program can clean up and exit safely', 'It works on zombies', 'No reason'], 1, 'SIGKILL gives no chance to save state.']],
  c: { t: 'The app <code>python3 stuck_app.py</code> (PID 777) ignores polite requests. Try SIGTERM first, then force it.', try: 'kill 777', steps: [['Send SIGTERM to 777 (it will be ignored)', ctx => ctx.events.some(e => e.type === 'signal' && e.pid === 777 && e.sig === 'TERM')], ['Kill it with SIGKILL', ctx => ctx.events.some(e => e.type === 'signal' && e.pid === 777 && e.sig === 'KILL')]] },
});
lesson('bgamp', {
  n: '& (background)', k: '&', s: 'Runs a command in the background so you get your prompt back immediately.',
  an: 'Putting a load of laundry on and walking away to cook dinner, instead of standing in front of the machine until it finishes.',
  nm: 'The ampersand <b>&amp;</b> at the end of a command line.',
  sx: 'COMMAND [ARGS] &', p: [['COMMAND [ARGS]', 'cmd', 'Any command.', true], ['&', 'opt', 'Don\'t wait for it; run it as a background job.', true]],
  ex1: 'sleep 100 &',
  sc: [['fork', 'the shell creates the child as usual', 'clone(…) = 2190'], ['setpgid', 'the child gets its own process group (so Ctrl+C in the terminal won\'t hit it)', 'setpgid(2190, 2190) = 0'], ['(no wait)', 'the shell does NOT call wait() — it prints [job] PID and shows the prompt', 'write(2, "[1] 2190\\n", 9) = 9'], ['SIGCHLD → wait4', 'when the child exits, the kernel signals the shell, which reaps it and reports “Done”', 'wait4(-1, …, WNOHANG, NULL) = 2190']],
  ch: 'A new process exists until it finishes. $! holds its PID.', out: '<code>[1] 2190</code> immediately; later <code>[1]+ Done …</code>. The job\'s own output still appears in your terminal (mixed with your typing!).', ec: 'The & line itself returns 0 at once; the job\'s real exit code is collected later (<code>wait %1; echo $?</code>).',
  f: [['&', '', 'Run in background.', 'sleep 60 &', true], ['$!', '', 'PID of the most recent background job.', 'echo $!', true], ['wait', '', 'Wait for background jobs to finish.', 'wait', true], ['jobs', '', 'List background jobs.', 'jobs', true], ['> log 2>&1 &', '', 'Background + capture output.', 'cmd > out.log 2>&1 &', false]],
  e: [['sleep 100 &', '[1] 2190', 'Job 1 with PID 2190.'], ['sleep 50 & sleep 60 &', '', 'Two jobs at once.'], ['jobs', '[1]-  Running  sleep 100 &\n[2]+  Running  sleep 60 &', 'List them.'], ['echo $!', '', 'PID of the last one.'], ['tar czf docs.tgz docs > /dev/null 2>&1 &', '', 'A quiet background task.']],
  u: `<p>Normally the shell <b>forks</b> a child and then <b>waits</b> for it. With &amp; it skips the wait, so you can keep working. The kernel tells the shell later (SIGCHLD) when the job finishes, and the shell prints “Done”.</p><p>Background jobs still belong to your terminal session: if you close the terminal, they get <b>SIGHUP</b> and usually die. Use <code>nohup</code>, <code>disown</code>, tmux/screen, or a systemd service for long-running work.</p><p>A background job that tries to READ from the terminal is stopped automatically (SIGTTIN).</p>`,
  adv: `<p>Job control uses process groups and sessions: each pipeline is one process group; the terminal has one foreground process group (<code>tcsetpgrp</code>). Keyboard signals (Ctrl+C → SIGINT, Ctrl+Z → SIGTSTP) go only to the foreground group. Background groups reading the tty get SIGTTIN; writing gets SIGTTOU only if <code>stty tostop</code>.</p>`,
  mi: [['long_task & then closing the terminal', 'The job receives SIGHUP and dies.', 'nohup long_task > out.log 2>&1 &'], ['cmd & with lots of output', 'Output scribbles over your prompt.', 'cmd > out.log 2>&1 &'], ['cd /tmp &', 'Runs cd in a background subshell — your shell doesn\'t move.', 'cd /tmp']],
  safe: '& changes only WHEN you get the prompt back — not what the command does.',
  r: [['jobs', 'List & manage background jobs.'], ['fg', 'Bring a job back to the foreground.'], ['nohup', 'Survive closing the terminal.'], ['bg', 'Resume a stopped job in the background.']],
  cs: ['<code>cmd &</code> run in background', '<code>[1] PID</code> = job number + PID', '<code>$!</code> last background PID', '<code>jobs</code> · <code>fg</code> · <code>wait</code>', 'Dies with the terminal unless <code>nohup</code>'],
  q: [['What does & make the shell skip?', ['fork()', 'exec()', 'wait()', 'exit()'], 2, 'The shell doesn\'t wait for the child.'], ['Which variable holds the PID of the last background job?', ['$$', '$?', '$!', '$#'], 2, '$! = last background PID.'], ['What happens to a & job when you close the terminal (by default)?', ['Nothing', 'It gets SIGHUP and usually dies', 'It becomes a daemon', 'It pauses'], 1, 'Use nohup or disown to survive.']],
  c: { t: 'Start <code>sleep 100</code> in the <b>background</b>.', try: 'sleep 100 &', chk: ctx => ctx.events.some(e => e.type === 'spawn' && /sleep/.test(e.name || '')) },
});
lesson('jobs', {
  n: 'jobs', s: 'Lists the background and stopped jobs of the current shell.',
  an: 'The ticket list at a dry cleaner\'s counter: “#1 shirts — in progress, #2 suit — on hold”.',
  nm: '<b>jobs</b>.',
  sx: 'jobs [-l] [-p] [%JOB]', p: [['jobs', 'cmd', 'Bash builtin.', true], ['[-l] [-p]', 'opt', '-l include PIDs, -p only PIDs.', false], ['[%JOB]', 'arg', 'A specific job.', false]],
  ex1: 'jobs -l',
  sc: [['(none)', 'builtin: bash prints its own internal job table (no kernel query needed)', '']],
  ch: 'Nothing.', out: '<code>[1]+  Running   sleep 100 &</code>. + = current job (default for fg/bg), - = previous.', ec: '0.',
  f: [['-l', '', 'Show PIDs too.', 'jobs -l', true], ['-p', '', 'Only PIDs.', 'jobs -p', false], ['-r / -s', '', 'Only running / only stopped.', 'jobs -s', false]],
  e: [['sleep 100 &', '[1] 2190', 'Create a job.'], ['jobs', '[1]+  Running   sleep 100 &', 'List.'], ['jobs -l', '[1]+ 2190 Running   sleep 100 &', 'With PID.'], ['kill -STOP %1; jobs', '[1]+  Stopped   sleep 100', 'A stopped job.'], ['kill %1', '', 'Clean up.']],
  u: `<p>Jobs are a <b>shell</b> concept: numbers like %1, %2 exist only in the shell that started them; another terminal can't see them (use ps there). Job specs: <code>%1</code>, <code>%+</code> / <code>%%</code> current, <code>%-</code> previous, <code>%sleep</code> by command prefix.</p><p>States: <b>Running</b> (in background), <b>Stopped</b> (paused by Ctrl+Z or SIGSTOP), <b>Done</b> (finished, reported once).</p>`,
  adv: `<p>bash keeps a <code>struct job</code> array; each job = a process group (pipeline). It learns about state changes through SIGCHLD + <code>waitpid(-1, …, WNOHANG|WUNTRACED|WCONTINUED)</code> and reports them before the next prompt (or immediately with <code>set -b</code>).</p>`,
  mi: [['jobs in another terminal', 'Empty — jobs are per shell.', 'ps -u $USER'], ['kill 1 (meaning job 1)', 'That targets PID 1!', 'kill %1'], ['Exiting with stopped jobs', 'bash warns “There are stopped jobs”.', 'jobs; then fg or kill them']],
  safe: 'Read-only.',
  r: [['fg', 'Bring a job to the foreground.'], ['bg', 'Resume a stopped job in the background.'], ['bgamp', 'Start jobs with &.'], ['ps', 'System-wide view.']],
  cs: ['<code>jobs</code> list · <code>jobs -l</code> with PIDs', '%1 = job 1 · %+ current · %- previous', 'Running / Stopped / Done', 'Per-shell only', 'Use with fg, bg, kill %N'],
  q: [['Are job numbers visible from another terminal?', ['Yes', 'No, they belong to one shell', 'Only for root', 'With -a'], 1, 'Jobs are a shell feature.'], ['How do you refer to job 2?', ['#2', '%2', '$2', '@2'], 1, '%2.'], ['What does + after [1] mean?', ['High priority', 'The current/default job', 'It uses more CPU', 'Finished'], 1, 'fg/bg without arguments act on it.']],
  c: { t: 'Start a background job, then list jobs with their PIDs.', try: 'sleep 200 &', steps: [['Have a background job (sleep 200 &)', ctx => S.jobs.length > 0], ['Run jobs -l', ctx => okRun(ctx, 'jobs') && ctx.line.includes('-l')]] },
});
lesson('bg', {
  n: 'bg', s: 'Resumes a stopped job, letting it continue in the background.',
  an: 'Un-pausing a video and minimizing the window: it keeps playing while you do something else.',
  nm: '<b>b</b>ack<b>g</b>round.',
  sx: 'bg [%JOB]', p: [['bg', 'cmd', 'Bash builtin.', true], ['[%JOB]', 'arg', 'Which job (default: current).', false]],
  ex1: 'bg %1',
  sc: [['kill(-pgid, SIGCONT)', 'sends SIGCONT to the job\'s process group so it runs again', 'kill(-2190, SIGCONT) = 0']],
  ch: 'The job\'s processes go from T (stopped) to R/S (running).', out: '<code>[1]+ sleep 100 &</code>', ec: '0, or 1 if no such job.',
  f: [['%N', '', 'Job number.', 'bg %2', true], ['(none)', '', 'Current job (+).', 'bg', true]],
  e: [['sleep 100', '', 'Foreground… now press Ctrl+Z to stop it.'], ['jobs', '[1]+  Stopped   sleep 100', 'It is paused.'], ['bg', '[1]+ sleep 100 &', 'Continues in the background.'], ['jobs', '[1]+  Running   sleep 100 &', 'Running again.'], ['kill %1', '', 'Clean up.']],
  u: `<p>Classic workflow: you start something long in the foreground, realise you need your prompt, press <b>Ctrl+Z</b> (SIGTSTP → job stopped), then type <b>bg</b> (SIGCONT → continues in background). Same as if you had started it with &amp;.</p>`,
  adv: `<p>bg marks the job as background (the terminal's foreground process group stays the shell) and sends SIGCONT to the whole process group (negative PID). If the job then tries to read from the terminal, it gets SIGTTIN and stops again.</p>`,
  mi: [['bg for an interactive editor', 'It immediately stops again (needs the keyboard).', 'fg'], ['bg 1', 'Works in bash, but %1 is clearer.', 'bg %1'], ['Expecting bg to survive closing the terminal', 'It still gets SIGHUP.', 'disown %1   or use nohup']],
  safe: 'Only resumes a paused job.',
  r: [['fg', 'Resume in the FOREGROUND instead.'], ['jobs', 'See what is stopped.'], ['signals', 'bg = SIGCONT.']],
  cs: ['<b>Ctrl+Z</b> stop, then <code>bg</code>', 'bg = send SIGCONT, keep in background', '<code>bg %2</code> a specific job', 'Same result as starting with &', 'Check with <code>jobs</code>'],
  q: [['Which signal does bg send?', ['SIGTERM', 'SIGSTOP', 'SIGCONT', 'SIGHUP'], 2, 'SIGCONT resumes.'], ['What key stops the foreground job?', ['Ctrl+C', 'Ctrl+Z', 'Ctrl+D', 'Ctrl+B'], 1, 'Ctrl+Z sends SIGTSTP.'], ['After bg, can you type new commands?', ['No', 'Yes', 'Only after it finishes', 'Only with sudo'], 1, 'It runs in the background.']],
  c: { t: 'Stop a job and resume it in the background: run <code>sleep 200</code>, press <b>Ctrl+Z</b>, then <code>bg</code>.', try: 'sleep 200', steps: [['Have a stopped job (Ctrl+Z)', ctx => S.jobs.some(j => j.st === 'Stopped') || ctx.events.some(e => e.type === 'bg')], ['Resume it with bg', ctx => ctx.events.some(e => e.type === 'bg')]] },
});
lesson('fg', {
  n: 'fg', s: 'Brings a background or stopped job to the foreground (your terminal).',
  an: 'Calling a dog back from the garden: it comes back to you and has your full attention again.',
  nm: '<b>f</b>ore<b>g</b>round.',
  sx: 'fg [%JOB]', p: [['fg', 'cmd', 'Bash builtin.', true], ['[%JOB]', 'arg', 'Which job (default: current).', false]],
  ex1: 'fg %1',
  sc: [['tcsetpgrp', 'gives the terminal to the job\'s process group (it now receives your keystrokes and Ctrl+C)', 'ioctl(255, TIOCSPGRP, [2190]) = 0'], ['kill SIGCONT', 'resumes it if it was stopped', 'kill(-2190, SIGCONT) = 0'], ['wait4', 'the shell waits, exactly like for a normal foreground command', 'wait4(-2190, …, WUNTRACED, NULL)']],
  ch: 'The job becomes the foreground job; the shell waits for it.', out: 'The command line of the job, then its output.', ec: 'The job\'s exit code when it finishes.',
  f: [['%N', '', 'Job number.', 'fg %2', true], ['(none)', '', 'Current job.', 'fg', true], ['%name', '', 'Job whose command starts with name.', 'fg %sleep', false]],
  e: [['sleep 30 &', '[1] 2190', 'Background job.'], ['fg', 'sleep 30', 'Now it occupies the terminal; Ctrl+C / Ctrl+Z work on it.'], ['fg %2', '', 'A specific job.'], ['(Ctrl+Z) then fg', '', 'Pause and resume in the foreground.'], ['jobs', '', 'Check before choosing.']],
  u: `<p>Only one process group at a time owns the terminal (the <b>foreground</b> group). It receives your keyboard input and keyboard signals (Ctrl+C, Ctrl+Z). fg hands that ownership to a job and waits; when it ends or is stopped, the shell takes the terminal back.</p>`,
  adv: `<p>Terminal ownership is <code>tty->pgrp</code>, set with <code>tcsetpgrp(fd, pgid)</code> (ioctl TIOCSPGRP). The line discipline sends SIGINT/SIGTSTP to that group when it sees ^C/^Z (configurable with <code>stty intr/susp</code>).</p>`,
  mi: [['fg in a script', '“no job control” — scripts run without job control.', 'wait $pid'], ['fg 2190 (a PID)', 'fg takes job specs, not PIDs.', 'fg %1'], ['Closing the terminal after fg', 'The job dies with SIGHUP.', 'nohup / tmux']],
  safe: 'Only changes which job owns the terminal.',
  r: [['bg', 'Resume in the background instead.'], ['jobs', 'List job numbers.'], ['bgamp', 'Start in background with &.']],
  cs: ['<code>fg</code> bring current job forward', '<code>fg %N</code> specific job', 'Foreground job gets Ctrl+C / Ctrl+Z', 'Shell waits again', 'Job specs, not PIDs'],
  q: [['What does fg do with a stopped job?', ['Kills it', 'Resumes it in the foreground', 'Moves it to background', 'Nothing'], 1, 'SIGCONT + terminal ownership.'], ['Who receives Ctrl+C?', ['All processes', 'The foreground process group', 'The shell only', 'Background jobs'], 1, 'Only the foreground group.'], ['fg %2 refers to…', ['PID 2', 'job number 2', 'the second-newest file', 'CPU 2'], 1, 'Job number.']],
  c: { t: 'Start <code>sleep 30 &</code> and bring it to the foreground with <code>fg</code>.', try: 'sleep 30 &', steps: [['Have a background job', ctx => S.jobs.length > 0 || ctx.events.some(e => e.type === 'spawn')], ['Bring it forward with fg', ctx => ctx.events.some(e => e.type === 'fg')]] },
});
lesson('nohup', {
  n: 'nohup', s: 'Runs a command immune to hang-ups, so it keeps running after you log out.',
  an: 'Telling a contractor: “keep working even if I hang up the phone” — and leaving them a notebook (nohup.out) to write their progress in.',
  nm: '<b>no</b> <b>h</b>ang-<b>up</b>.',
  sx: 'nohup COMMAND [ARGS] [&]', p: [['nohup', 'cmd', 'Wrapper program.', true], ['COMMAND [ARGS]', 'arg', 'The command to protect.', true], ['&', 'opt', 'Almost always combined with & to also run it in the background.', false]],
  ex1: 'nohup sleep 300 &',
  sc: [['signal(SIGHUP, SIG_IGN)', 'sets SIGHUP to “ignore” — ignored signals stay ignored across exec()', 'rt_sigaction(SIGHUP, {sa_handler=SIG_IGN}, NULL, 8) = 0'], ['openat nohup.out', 'if stdout is a terminal, redirects it to nohup.out (append)', 'openat(AT_FDCWD, "nohup.out", O_WRONLY|O_CREAT|O_APPEND, 0600) = 3'], ['execve', 'becomes the real command', 'execve("/usr/bin/sleep", ["sleep", "300"], …) = 0']],
  ch: 'Creates/appends <code>nohup.out</code> if output wasn\'t redirected.', out: '<code>nohup: ignoring input and appending output to \'nohup.out\'</code> on stderr.', ec: 'The command\'s; 125 if nohup failed, 126/127 if the command couldn\'t run.',
  f: [['&', '', 'Background as well.', 'nohup cmd &', true], ['> file 2>&1', '', 'Choose your own log file.', 'nohup cmd > run.log 2>&1 &', true]],
  e: [['nohup sleep 300 &', "[1] 2191\nnohup: ignoring input and appending output to 'nohup.out'", 'Survives logout.'], ['nohup ./script.sh > run.log 2>&1 &', '', 'Custom log, no nohup.out.'], ['cat nohup.out', '', 'See captured output.'], ['jobs; ps aux | grep sleep', '', 'Still running.'], ['disown %1', '', 'Alternative: remove a running job from the shell\'s job table.']],
  u: `<p>When a terminal closes, the kernel sends <b>SIGHUP</b> to the session, and bash forwards it to its jobs. Default action: terminate. nohup sets SIGHUP to <i>ignored</i>; because ignored dispositions survive exec(), the program never sees it.</p><p>For real services use <b>systemd</b> units; for interactive long sessions use <b>tmux</b> or <b>screen</b> (you can reattach later).</p>`,
  adv: `<p>nohup also redirects stdin from /dev/null if it's a terminal (so the job won't get SIGTTIN) and stderr to stdout. Programs that install their own SIGHUP handler can override the ignore. <code>disown -h</code> tells bash not to forward SIGHUP to a job; <code>setsid cmd</code> starts it in a new session with no controlling terminal.</p>`,
  mi: [['nohup cmd (without &)', 'Still occupies your terminal until done.', 'nohup cmd &'], ['Expecting nohup.out in /tmp', 'It goes to the current directory (or $HOME if not writable).', 'nohup cmd > /tmp/out.log 2>&1 &'], ['nohup for a server you want restarted on crash/boot', 'nohup doesn\'t restart or start at boot.', 'Write a systemd service']],
  safe: 'nohup only changes signal handling and output location.',
  r: [['bgamp', '& alone dies when the terminal closes.'], ['systemctl', 'Proper long-running services.'], ['signals', 'SIGHUP explained.']],
  cs: ['<code>nohup cmd &</code> survives logout', 'Ignores SIGHUP', 'Output → nohup.out (unless redirected)', '<code>disown</code> = after-the-fact alternative', 'Services → systemd, sessions → tmux'],
  q: [['What signal does nohup make the command ignore?', ['SIGKILL', 'SIGHUP', 'SIGTERM', 'SIGINT'], 1, 'Hang-up.'], ['Where does output go by default?', ['/dev/null', 'nohup.out', 'syslog', 'the screen'], 1, 'Appended to nohup.out.'], ['Does nohup restart a crashed program?', ['Yes', 'No', 'Only with -r', 'Only as root'], 1, 'Use systemd for that.']],
  c: { t: 'Start <code>sleep 300</code> so that it would survive logging out.', try: 'nohup sleep 300 &', chk: ctx => ran(ctx, 'nohup') && S.procs.some(p => p.hup) },
});

/* ======================= SEARCH ======================= */
lesson('find', {
  n: 'find', s: 'Searches a directory tree for files by name, type, size, age, owner, permissions… and can act on them.',
  an: 'A librarian walking every aisle and shelf, checking each book against your list of criteria — slow but thorough and always up to date.',
  nm: '<b>find</b>.',
  sx: 'find [PATH...] [TESTS] [ACTIONS]', p: [['find', 'cmd', 'The command.', true], ['[PATH...]', 'arg', 'Where to start (default .).', false], ['[TESTS]', 'opt', '-name, -type, -size, -mtime, -user, -perm… (all must match).', false], ['[ACTIONS]', 'opt', '-print (default), -delete, -exec CMD {} \\;, -ls.', false]],
  ex1: 'find . -name "*.log" -size +1M',
  sc: [['openat / getdents64', 'opens each directory and reads its entries, recursively', 'getdents64(4, /* 6 entries */, 32768) = 208'], ['newfstatat (×N)', 'stats every entry to test type, size, time, owner, mode', 'newfstatat(4, "app.log", {st_mode=S_IFREG|0644, st_size=2516582, …}, AT_SYMLINK_NOFOLLOW) = 0'], ['write', 'prints each path that passes all tests', 'write(1, "./logs/app.log\\n", 15) = 15'], ['fork/execve (-exec)', 'with -exec, runs a command for each match', 'execve("/usr/bin/gzip", ["gzip", "./logs/app.log"], …)']],
  ch: 'Nothing unless you use -delete or -exec.', out: 'One path per line. Unreadable directories produce “Permission denied” on stderr.', ec: '0 = traversal OK, 1 = some errors (e.g. permission denied) — even if matches were found.',
  f: [['-name PAT', '', 'Name matches a glob (quote it!). -iname ignores case.', 'find . -name "*.txt"', true], ['-type f|d|l', '', 'Regular file, directory, symlink.', 'find /etc -type d', true], ['-size +N[kMG]', '', 'Bigger (+) / smaller (-) than N.', 'find / -size +100M', true], ['-mtime ±N', '', 'Modified more (+) / less (-) than N days ago.', 'find logs -mtime -7', true], ['-user U', '', 'Owned by U.', 'find /home -user alice', false], ['-perm MODE', '', 'Exact (644), all bits (-4000), any bit (/222).', 'find / -perm -4000', false], ['-maxdepth N', '', 'Don\'t descend more than N levels.', 'find . -maxdepth 1', true], ['-empty', '', 'Empty files/dirs.', 'find . -empty', false], ['-exec CMD {} \\;', '', 'Run CMD for each match ({} = path).', 'find . -name "*.tmp" -exec rm {} \\;', true], ['-exec CMD {} +', '', 'Run CMD once with many paths (faster).', 'find . -name "*.log" -exec gzip {} +', false], ['-delete', '', 'Delete matches.', 'find /tmp -name "*.tmp" -delete', false], ['! / -o', '', 'NOT / OR.', 'find . ! -name "*.txt"', false]],
  e: [['find . -name "*.txt"', './fruits.txt\n./notes.txt\n./docs/readme.txt…', 'All .txt files below here.'], ['find . -type d', '', 'Only directories.'], ['find logs -size +1M', './logs/app.log\n./logs/error.log', 'Files bigger than 1 MiB.'], ['find . -mtime -2 -type f', '', 'Changed in the last 2 days.'], ['find / -perm -4000 2>/dev/null', '', 'All setuid programs, errors hidden.'], ['find . -name "*.log" -size +1M -exec gzip {} \\;', '', 'Compress each big log.']],
  u: `<p>find <b>walks the filesystem live</b>: it opens every directory and stats every entry, so results are always current but large trees take time. Tests are combined with AND by default; use <code>-o</code> for OR and <code>!</code> for NOT.</p><p><b>Quote patterns</b>: <code>find . -name "*.txt"</code>. Without quotes, the shell may expand *.txt in the current directory first, and find receives a wrong list.</p><p><b>-exec … {} \\;</b> runs once per file (the <code>\\;</code> ends the command and is escaped so the shell passes it through). <b>{} +</b> batches many files into one command, like xargs.</p><p><b>Size units</b>: <code>c</code> bytes, <code>k</code> KiB, <code>M</code> MiB, <code>G</code> GiB; values are rounded UP, so <code>-size -1M</code> only matches empty files — use <code>-size -1024k</code>.</p>`,
  adv: `<p>GNU find uses the fts library with <code>O_NOATIME</code>/<code>O_DIRECTORY</code>, and often avoids stat() thanks to <code>d_type</code> from getdents64 when only -type/-name are needed. <code>-mtime</code> compares (now − st_mtime)/86400 truncated, which is why -mtime 0 means “within 24 h”. Use <code>-xdev</code> to stay on one filesystem, <code>-print0 | xargs -0</code> for names with spaces/newlines.</p>`,
  mi: [['find . -name *.txt', 'If txt files exist in ., the shell expands the glob → wrong results or “paths must precede expression”.', 'find . -name "*.txt"'], ['find / -name x (as user)', 'Pages of “Permission denied”.', 'find / -name x 2>/dev/null'], ['find . -delete -name "*.tmp"', 'Order matters! -delete runs before -name filters → deletes EVERYTHING.', 'find . -name "*.tmp" -delete'], ['find . -exec rm {} ;', 'Missing backslash: the shell eats the ;.', 'find . -name "*.tmp" -exec rm {} \\;']],
  w: '<b>-delete and -exec rm</b> act on every match with no confirmation, and expressions are evaluated left to right: putting <code>-delete</code> before the tests deletes everything under the path. Always run the same find with <code>-print</code> first, check the list, then add <code>-delete</code>. Use <code>-ok</code> instead of <code>-exec</code> to confirm each file.',
  r: [['locate', 'Instant name search from a database — but may be out of date.'], ['grep-r', 'Search file CONTENTS rather than names/attributes.'], ['xargs', 'find … -print0 | xargs -0 cmd for big batches.'], ['du', 'Find what takes space.']],
  cs: ['<code>find . -name "*.txt"</code> (quote!)', '<code>-type f/d</code> · <code>-size +1M</code> · <code>-mtime -7</code>', '<code>2>/dev/null</code> hide permission errors', '<code>-exec cmd {} \\;</code> per file · <code>{} +</code> batch', 'Preview before <code>-delete</code>'],
  q: [['Why quote "*.txt" in find -name?', ['Style', 'So the shell doesn\'t expand it before find sees it', 'find needs quotes always', 'For speed'], 1, 'find must receive the pattern itself.'], ['Which finds files modified in the last 3 days?', ['-mtime +3', '-mtime -3', '-mtime 3', '-atime 3'], 1, '-N = less than N days ago.'], ['What is {} in -exec?', ['An empty command', 'Placeholder for each found path', 'A glob', 'The current dir'], 1, 'Replaced by the path.']],
  c: { t: 'Find all <code>.log</code> files <b>larger than 1 MB</b> under your home.', try: 'find . -name "*.log" -size +1M', chk: ctx => okRun(ctx, 'find') && ctx.line.includes('-size') && outOf(ctx).includes('app.log') },
});
lesson('locate', {
  n: 'locate', s: 'Finds files by name instantly, using a pre-built database of all paths.',
  an: 'Looking a book up in the library catalogue instead of walking the shelves — instant, but the catalogue was printed last night, so today\'s new books aren\'t in it yet.',
  nm: '<b>locate</b>.',
  sx: 'locate [OPTIONS] PATTERN...', p: [['locate', 'cmd', 'Database search (plocate/mlocate).', true], ['[OPTIONS]', 'opt', '-i ignore case, -c count, -b basename only, -n limit.', false], ['PATTERN...', 'arg', 'Substring (or glob) to look for in full paths.', true]],
  ex1: 'locate notes.txt',
  sc: [['openat', 'opens the database, not the filesystem', 'openat(AT_FDCWD, "/var/lib/plocate/plocate.db", O_RDONLY) = 3'], ['read / mmap', 'scans the compressed index', 'mmap(NULL, 2048000, PROT_READ, MAP_SHARED, 3, 0) = 0x7f…'], ['newfstatat (opt.)', 'may check you can access each result\'s directory', ''], ['write', 'prints matching paths', 'write(1, "/home/user/notes.txt\\n", 21) = 21']],
  ch: 'Nothing.', out: 'Full paths containing the pattern.', ec: '0 = found, 1 = nothing found.',
  f: [['-i', '--ignore-case', 'Case-insensitive.', 'locate -i README', true], ['-c', '--count', 'Only count matches.', 'locate -c .conf', false], ['-b', '--basename', 'Match only the file name, not the full path.', 'locate -b notes', true], ['-n N', '--limit', 'Stop after N results.', 'locate -n 5 .log', false], ['updatedb', '', '(separate command, root) rebuild the database.', 'sudo updatedb', true]],
  e: [['locate notes.txt', '/home/user/notes.txt', 'Instant.'], ['touch zz.txt; locate zz.txt', '', 'Nothing — the new file isn\'t in the database yet!'], ['sudo updatedb; locate zz.txt', '/home/user/zz.txt', 'After a refresh, it appears.'], ['locate -i README', '', 'Ignore case.'], ['locate -c .conf', '', 'How many paths contain .conf.']],
  u: `<p>locate doesn't look at the disk at all — it searches a database built by <b>updatedb</b>, normally run once a day by a cron/systemd timer. That makes it extremely fast but potentially <b>stale</b>: new files are missing and deleted files may still appear. find is slower but always current.</p>`,
  adv: `<p>plocate stores a trigram-indexed, zstd-compressed list of paths in <code>/var/lib/plocate/plocate.db</code>; updatedb's settings (pruned paths and filesystems like /tmp, nfs) are in <code>/etc/updatedb.conf</code>. Results are filtered by your access rights so you can't discover names in directories you can't read.</p>`,
  mi: [['locate newfile right after creating it', 'Not found — database is old.', 'sudo updatedb && locate newfile'], ['locate *.txt', 'Shell expands the glob first.', 'locate "*.txt"   # or locate .txt'], ['Assuming locate on a fresh system works', '“no database file”.', 'sudo apt install plocate && sudo updatedb']],
  safe: 'Read-only.',
  r: [['find', 'Live search with many criteria (size, date, owner) — use when results must be current.'], ['which', 'Find only programs in $PATH.']],
  cs: ['<code>locate name</code> instant path search', 'Uses a database, not the disk', '<code>sudo updatedb</code> to refresh', 'New files missing until refresh', '<code>-i</code> ignore case · <code>-b</code> basename'],
  q: [['Why might locate not find a file you just created?', ['Bug', 'The database hasn\'t been updated', 'It needs sudo', 'It only finds .txt'], 1, 'Run updatedb.'], ['What updates locate\'s database?', ['cron only', 'updatedb', 'find -update', 'locate -u'], 1, 'updatedb (usually scheduled daily).'], ['Which is always up to date: find or locate?', ['find', 'locate', 'both', 'neither'], 0, 'find walks the live filesystem.']],
  c: { t: 'Create <code>zz.txt</code>, see that locate misses it, refresh the database, and find it.', try: 'touch zz.txt', steps: [['locate something successfully', ctx => ran(ctx, 'locate')], ['Run sudo updatedb', ctx => ran(ctx, 'updatedb') && ctx.code === 0], ['locate zz.txt finds it', ctx => ran(ctx, 'locate') && outOf(ctx).includes('zz.txt')]] },
});
lesson('which', {
  n: 'which', s: 'Shows the full path of the program that would run for a command name.',
  an: 'Asking the receptionist “if I call ‘Dr. Smith’, which office will pick up?” — they check the directory in order and tell you the first match.',
  nm: '<b>which</b> (program?).',
  sx: 'which [-a] NAME...', p: [['which', 'cmd', 'The command.', true], ['[-a]', 'opt', 'Show ALL matches in $PATH, not just the first.', false], ['NAME...', 'arg', 'Command names.', true]],
  ex1: 'which ls',
  sc: [['newfstatat (×dirs)', 'checks each $PATH directory in order for an executable called NAME', 'newfstatat(AT_FDCWD, "/usr/local/bin/ls", …) = -1 ENOENT'], ['access(X_OK)', 'confirms it is executable', 'faccessat(AT_FDCWD, "/usr/bin/ls", X_OK) = 0'], ['write', 'prints the path', 'write(1, "/usr/bin/ls\\n", 12) = 12']],
  ch: 'Nothing.', out: 'Path(s) of executables. Nothing for builtins/aliases.', ec: '0 = all found, 1 = some not found.',
  f: [['-a', '', 'All matches along $PATH.', 'which -a python3', true]],
  e: [['which ls', '/usr/bin/ls', 'Where ls lives.'], ['which cd', '', 'Nothing — cd is a builtin, not a file.'], ['type cd ls ll', 'cd is a shell builtin\nls is /usr/bin/ls\nll is aliased to `ls -la\'', 'type knows builtins and aliases too.'], ['echo $PATH', '/usr/local/sbin:/usr/local/bin:…', 'The search order.'], ['which tree || echo "not installed"', '', 'Use the exit code.']],
  u: `<p>When you type a command name without a slash, bash checks: alias → function → builtin → <b>$PATH</b> directories, left to right. The first executable wins. <code>which</code> only does the last step; <code>type</code> (a bash builtin) shows the whole truth.</p><p>The current directory is <b>not</b> in $PATH (for security: someone could drop a fake “ls” into /tmp). That's why you run your own scripts as <code>./script.sh</code>.</p>`,
  adv: `<p>bash caches PATH lookups in a hash table (<code>hash</code> builtin shows it; <code>hash -r</code> clears it after you move binaries). <code>command -v NAME</code> is the POSIX, script-safe equivalent of which. Programs can also be found via <code>/proc/PID/exe</code> for running processes.</p>`,
  mi: [['which cd', 'Prints nothing — not an error in your system.', 'type cd'], ['Adding . to the front of PATH', 'Security risk: a malicious ./ls would run instead of /usr/bin/ls.', 'Use ./script, or put scripts in ~/bin'], ['which in scripts for checks', 'Not available everywhere / inconsistent.', 'command -v tool >/dev/null || echo missing']],
  safe: 'Read-only.',
  r: [['find', 'find searches anything; which only $PATH.'], ['locate', 'All files by name.'], ['export', 'Change $PATH.']],
  cs: ['<code>which cmd</code> → path of the program', '<code>which -a</code> all copies', 'Builtins/aliases: use <code>type</code>', 'Order = $PATH left to right', '. is not in $PATH → use ./script'],
  q: [['Why does which cd print nothing?', ['cd is broken', 'cd is a builtin, not a file', 'Needs sudo', 'cd is in /root'], 1, 'Use type cd.'], ['In which order is $PATH searched?', ['Random', 'Left to right', 'Right to left', 'Alphabetical'], 1, 'First match wins.'], ['Why must you type ./script.sh?', ['Scripts need dots', 'The current directory isn\'t in $PATH', 'For speed', 'Because of permissions'], 1, 'Security: . is not searched.']],
  c: { t: 'Find out where the <code>ls</code> program lives, and what kind of command <code>cd</code> is.', try: 'which ls', steps: [['which ls', ctx => okRun(ctx, 'which') && outOf(ctx).includes('/usr/bin/ls')], ['type cd', ctx => ran(ctx, 'type') && outOf(ctx).includes('builtin')]] },
});
lesson('grep-r', {
  n: 'grep -r', k: 'grep', s: 'Searches the CONTENT of every file in a directory tree for a pattern.',
  an: 'Instead of checking one document, you send a team through every filing cabinet in the office to find every page that mentions a word.',
  nm: '<b>grep</b> + <b>-r</b> (<b>r</b>ecursive).',
  sx: 'grep -r [OPTIONS] PATTERN [DIR]...', p: [['grep -r', 'cmd', 'grep in recursive mode.', true], ['[OPTIONS]', 'opt', '-n line numbers, -i ignore case, -l names only, --include=GLOB.', false], ['PATTERN', 'arg', 'Text or regex.', true], ['[DIR]...', 'arg', 'Where to start (default: .).', false]],
  ex1: 'grep -rn TODO .',
  sc: [['openat/getdents64', 'walks every directory', 'getdents64(3, /* 9 entries */, 32768) = 280'], ['openat/read (×files)', 'reads every regular file', 'read(4, "# TODO\\n- [x] install…", 98304) = 66'], ['write', 'prints file:line:text', 'write(1, "./docs/todo.md:1:# TODO\\n", 23) = 23']],
  ch: 'Nothing.', out: '<code>path:line</code> or <code>path:linenumber:line</code> for every match.', ec: '0 match, 1 none, 2 error.',
  f: [['-r', '--recursive', 'Recurse (doesn\'t follow symlinks; -R does).', 'grep -r x .', true], ['-n', '', 'Line numbers.', 'grep -rn x .', true], ['-l', '', 'Only file names.', 'grep -rl nginx /etc', true], ['-i', '', 'Ignore case.', 'grep -ri error logs', true], ['--include=GLOB', '', 'Only files matching GLOB.', 'grep -r --include="*.md" TODO .', false], ['--exclude-dir=D', '', 'Skip directories.', 'grep -r --exclude-dir=.git x .', false], ['-w', '', 'Whole words.', 'grep -rw app .', false]],
  e: [['grep -r TODO .', './docs/todo.md:# TODO\n./notes.txt:TODO: learn pipes', 'Every file mentioning TODO.'], ['grep -rn ERROR logs', '', 'With line numbers.'], ['grep -rl nginx /etc', '/etc/nginx/nginx.conf', 'Which config files mention nginx.'], ['grep -ri "linux" docs', '', 'Case-insensitive.'], ['grep -r --include="*.md" TODO .', '', 'Only Markdown files.']],
  u: `<p>grep -r combines “walk the tree” (like find) with “search content” (like grep). It skips binary files by default (“Binary file … matches”). For big code bases, tools like <code>ripgrep (rg)</code> are faster and respect .gitignore.</p><p>Equivalent with find: <code>find . -type f -exec grep -n PATTERN {} +</code> — useful when you need find's filters (size, age).</p>`,
  adv: `<p>GNU grep -r uses fts and skips devices/FIFOs; it follows symlinks only on the command line (-R follows all). Files are mmap'd/read in large chunks and searched with Boyer–Moore/DFA before line boundaries are computed, which makes it fast on large trees.</p>`,
  mi: [['grep TODO *', 'Doesn\'t enter subdirectories (“Is a directory”).', 'grep -r TODO .'], ['grep -r pattern / (as user)', 'Very slow, full of permission errors, may hang on /proc or /dev.', 'grep -r pattern /etc 2>/dev/null'], ['grep -r password ~ > results.txt (results.txt inside ~)', 'grep may read its own growing output file.', 'Write results outside the searched tree']],
  safe: 'Read-only.',
  r: [['grep', 'Single files / pipes.'], ['find', 'Search by name/size/date instead of content.'], ['xargs', 'find … | xargs grep for complex selections.']],
  cs: ['<code>grep -r word dir</code> search all files', '<code>-n</code> line numbers · <code>-l</code> names only', '<code>--include="*.conf"</code> filter files', '<code>2>/dev/null</code> hide errors', 'Content search (find = name search)'],
  q: [['What does grep -rl print?', ['Matching lines', 'Only names of matching files', 'Line counts', 'Directories'], 1, '-l = files-with-matches.'], ['grep -r vs find -name: which searches CONTENT?', ['grep -r', 'find -name', 'both', 'neither'], 0, 'find -name matches names.'], ['How to limit grep -r to .conf files?', ['-name "*.conf"', '--include="*.conf"', '-type conf', '*.conf -r'], 1, '--include=GLOB.']],
  c: { t: 'Search your whole home directory for files containing <b>TODO</b>, with line numbers.', try: 'grep -rn TODO .', chk: ctx => okRun(ctx, 'grep') && /-\w*r|-R|--recursive/.test(ctx.line) && outOf(ctx).includes('TODO') },
});

/* ======================= ARCHIVES ======================= */
lesson('tar', {
  n: 'tar', s: 'Bundles many files and folders into one archive file (and extracts them again), optionally compressed.',
  an: 'Packing a moving box: everything from a room goes into one box with a label (archive). Adding -z is vacuum-sealing the box so it takes less space.',
  nm: '<b>t</b>ape <b>ar</b>chive — originally for writing backups to magnetic tape.',
  sx: 'tar -c|-x|-t [-z] [-v] -f ARCHIVE [FILES...]', p: [['tar', 'cmd', 'The command.', true], ['-c|-x|-t', 'opt', 'Mode: create, extract, or list (exactly one).', true], ['[-z] [-v]', 'opt', '-z gzip, -j bzip2, -J xz; -v verbose.', false], ['-f ARCHIVE', 'arg', 'Archive file name (f must be the last letter in a group, since it takes the name).', true], ['[FILES...]', 'arg', 'What to pack (for -c), or which entries to extract.', false]],
  ex1: 'tar -czvf docs.tar.gz docs',
  sc: [['openat (archive)', 'creates the output file', 'openat(AT_FDCWD, "docs.tar.gz", O_WRONLY|O_CREAT|O_TRUNC, 0666) = 3'], ['pipe + fork (gzip)', 'with -z, tar pipes its stream through a gzip process', 'pipe2([4, 5], 0) = 0; clone(…) = 2210'], ['getdents64 / newfstatat', 'walks the folder and stats each file for the header (name, mode, owner, size, mtime)', 'newfstatat(AT_FDCWD, "docs/report.txt", …) = 0'], ['read / write', 'writes a 512-byte header followed by the file data, for every file', 'write(5, "docs/report.txt\\0\\0…", 10240) = 10240']],
  ch: '-c creates a new archive (overwriting an existing one with the same name!). -x creates/overwrites files in the current directory (or -C dir).', out: 'Nothing, or file names with -v. -t lists contents.', ec: '0 = OK, 1 = some files differ/changed, 2 = fatal error.',
  f: [['-c', '--create', 'Create an archive.', 'tar -cf a.tar dir', true], ['-x', '--extract', 'Extract.', 'tar -xf a.tar', true], ['-t', '--list', 'List contents.', 'tar -tf a.tar', true], ['-f FILE', '--file', 'Archive file name.', 'tar -cf out.tar …', true], ['-z', '--gzip', 'Compress/decompress with gzip (.tar.gz/.tgz).', 'tar -czf a.tgz dir', true], ['-v', '--verbose', 'List files as processed.', 'tar -xzvf a.tgz', true], ['-j / -J', '', 'bzip2 / xz compression.', 'tar -cJf a.tar.xz dir', false], ['-C DIR', '--directory', 'Extract into (or create from) DIR.', 'tar -xzf a.tgz -C /tmp', true], ['--exclude=PAT', '', 'Skip matching paths.', 'tar -czf a.tgz --exclude="*.log" dir', false], ['-p', '', 'Preserve permissions (default for root).', 'tar -xpf a.tar', false]],
  e: [['tar -czvf docs.tar.gz docs', 'docs/\ndocs/readme.txt\ndocs/report.txt\ndocs/todo.md', 'Create a compressed archive of docs.'], ['tar -tzf docs.tar.gz', '', 'List what\'s inside without extracting.'], ['mkdir restore; tar -xzvf docs.tar.gz -C restore', '', 'Extract somewhere else.'], ['tar -cf both.tar notes.txt data.csv', '', 'Archive without compression.'], ['tar -czf site.tgz --exclude="*.css" projects/website', '', 'Exclude files.'], ['ls -l docs.tar.gz', '', 'Much smaller than the original text.']],
  u: `<p><b>Archive ≠ compression.</b> tar only concatenates files (each with a 512-byte header holding name, permissions, owner, size, time) into one stream. Compression is a separate step — <code>-z</code> just pipes the stream through gzip. That's why the extension is <code>.tar.gz</code>.</p><p>Memory aid: <b>c</b>reate <b>z</b>ipped <b>v</b>erbose <b>f</b>ile = <code>-czvf</code>; e<b>x</b>tract = <code>-xzvf</code>; lis<b>t</b> = <code>-tzf</code>. The <code>f</code> must come last in the group because the next word is the file name.</p><p>tar stores paths relative to what you gave it; avoid absolute paths so extraction doesn't overwrite system files.</p>`,
  adv: `<p>The ustar/GNU format: each member = 512-byte header (name 100 bytes + prefix 155, mode, uid/gid, size in octal, mtime, typeflag, checksum) + data padded to 512 bytes; the archive ends with two zero blocks. Because .tar.gz is one compressed stream, listing or extracting one file requires decompressing from the beginning — unlike zip, which compresses each member separately with a central directory.</p>`,
  mi: [['tar -cvf docs.tar.gz docs', 'Named .gz but NOT compressed (no -z).', 'tar -czvf docs.tar.gz docs'], ['tar -czvf docs', 'docs becomes the ARCHIVE name; nothing to archive → error (or overwrites!).', 'tar -czvf docs.tar.gz docs'], ['tar -xzf backup.tgz (in the wrong directory)', 'Files are extracted into the current dir and may overwrite existing ones.', 'tar -tzf backup.tgz first, then -C target/']],
  w: '<b>Extracting overwrites existing files</b> with the same paths, silently. Always list first (<code>tar -tzf</code>) and extract into a fresh directory with <code>-C</code>. Archives from untrusted sources may contain absolute paths or ../ (GNU tar strips them by default — keep it that way). Also: <code>tar -cf name.tar</code> overwrites an existing archive of that name.',
  r: [['gzip', 'Compress a single file (tar handles many).'], ['zip', 'Windows-friendly archives with per-file compression.'], ['rsync', 'For backups that you update repeatedly.']],
  cs: ['Create: <code>tar -czvf out.tar.gz dir</code>', 'List: <code>tar -tzf out.tar.gz</code>', 'Extract: <code>tar -xzvf out.tar.gz -C dest</code>', 'z = gzip · j = bzip2 · J = xz', 'f is last, followed by the archive name'],
  q: [['What does -z do?', ['Zip format', 'Filter through gzip', 'Zero padding', 'Verbose'], 1, 'gzip compression.'], ['Which lists contents without extracting?', ['-l', '-t', '-x', '-c'], 1, '-t = list.'], ['Why must f be the last letter in -czvf?', ['Tradition', 'f takes the next argument as the archive name', 'Alphabetical', 'It doesn\'t matter'], 1, '-czfv would make "v" the file name.']],
  c: { t: 'Create a <b>gzip-compressed</b> archive <code>docs.tar.gz</code> of the docs folder, then list its contents.', try: 'tar -czvf docs.tar.gz docs', steps: [['docs.tar.gz exists and is compressed', ctx => { const r = HP('docs.tar.gz'); const a = r.n && unpack('TAR', r.n.data); return a && a.z; }], ['List it with tar -t', ctx => ctx.events.some(e => e.type === 'archive' && e.mode === 'list')]] },
});
lesson('gzip', {
  n: 'gzip', s: 'Compresses a single file into file.gz (and gunzip / gzip -d restores it).',
  an: 'Vacuum-packing one sweater: same sweater, much smaller package. You unpack it to wear it again.',
  nm: '<b>G</b>NU <b>zip</b>.',
  sx: 'gzip [OPTIONS] FILE...   |   gunzip FILE.gz...', p: [['gzip', 'cmd', 'The compressor (gunzip = gzip -d).', true], ['[OPTIONS]', 'opt', '-k keep original, -d decompress, -v verbose, -1…-9 speed vs size.', false], ['FILE...', 'arg', 'Files to (de)compress. Each is processed separately.', true]],
  ex1: 'gzip -v notes.txt',
  sc: [['openat (input)', 'opens the original', 'openat(AT_FDCWD, "notes.txt", O_RDONLY|O_NOCTTY) = 3'], ['openat (output)', 'creates notes.txt.gz', 'openat(AT_FDCWD, "notes.txt.gz", O_WRONLY|O_CREAT|O_EXCL, 0600) = 4'], ['read → DEFLATE → write', 'compresses in a streaming way', 'write(4, "\\37\\213\\10\\10…", 64) = 64'], ['fchmod / utimensat', 'copies mode and time to the .gz', 'fchmod(4, 0644) = 0'], ['unlinkat', 'deletes the original (unless -k)', 'unlinkat(AT_FDCWD, "notes.txt", 0) = 0']],
  ch: 'file → file.gz; the original is <b>deleted</b> by default.', out: 'Nothing; with -v the compression ratio.', ec: '0 OK, 1 error, 2 warning.',
  f: [['-k', '--keep', 'Keep the original file.', 'gzip -k big.log', true], ['-d', '--decompress', 'Decompress (same as gunzip).', 'gzip -d f.gz', true], ['-v', '--verbose', 'Show ratio.', 'gzip -v f', true], ['-l', '--list', 'Show compressed/uncompressed sizes.', 'gzip -l f.gz', false], ['-c', '--stdout', 'Write to stdout, keep files.', 'gzip -c f > f.gz', false], ['-1 … -9', '', 'Fast … best compression (default 6).', 'gzip -9 f', false], ['-r', '--recursive', 'Compress every file in a directory tree (each separately).', 'gzip -r logs', false]],
  e: [['gzip -v notes.txt', 'notes.txt:  68.3% -- replaced with notes.txt.gz', 'Compress; original removed.'], ['gunzip notes.txt.gz', '', 'Back to normal.'], ['gzip -k logs/app.log; ls logs', 'app.log  app.log.gz …', 'Keep the original.'], ['gzip -l logs/app.log.gz', '', 'Sizes and ratio.'], ['zcat logs/app.log.gz | head -2', '', 'Read without decompressing to disk (real Linux).']],
  u: `<p>gzip uses <b>DEFLATE</b> (LZ77 + Huffman coding): repeated sequences are replaced by short back-references. Text and logs often shrink to 10–30%; JPEGs, MP3s, videos and .zip/.gz files are already compressed and barely shrink at all.</p><p>gzip works on <b>one file at a time</b>. To compress a folder, bundle it with <code>tar</code> first (<code>tar -czf</code>). Tools like <code>zcat</code>, <code>zless</code>, <code>zgrep</code> read .gz files directly.</p>`,
  adv: `<p>Format (RFC 1952): magic <code>1f 8b</code>, method 08 (deflate), flags, mtime, original name, then deflate blocks and a CRC32 + original size (mod 2³²) trailer. The 32 KiB sliding window limits how far back matches can reach; xz (LZMA) and zstd use bigger windows for better ratios. Multi-threaded drop-in: <code>pigz</code>.</p>`,
  mi: [['gzip docs', '“docs is a directory -- ignored”.', 'tar -czf docs.tar.gz docs'], ['gzip important.txt (expecting a copy)', 'The original is gone — only important.txt.gz remains.', 'gzip -k important.txt'], ['gzip photo.jpg to save space', 'Almost no gain.', 'Leave already-compressed media as is']],
  w: 'gzip and gunzip <b>delete the input file</b> after success. If you need the original, use <code>-k</code>. Don\'t gzip a log that a program is still writing to — the program keeps writing to the deleted file.',
  r: [['tar', 'Bundle folders, then compress (tar -z).'], ['zip', 'Archive + compression in one, Windows-friendly.'], ['du', 'Check sizes before and after.']],
  cs: ['<code>gzip f</code> → f.gz (original removed!)', '<code>gunzip f.gz</code> or <code>gzip -d</code>', '<code>-k</code> keep original · <code>-v</code> ratio', 'One file at a time — folders: tar -czf', 'zcat / zgrep read .gz directly'],
  q: [['What happens to notes.txt after gzip notes.txt?', ['Kept', 'Replaced by notes.txt.gz', 'Moved to /tmp', 'Renamed .bak'], 1, 'Use -k to keep it.'], ['Can gzip compress a directory directly?', ['Yes', 'No — use tar -z', 'Only with -r into one file', 'Only as root'], 1, '-r compresses each file separately; to get one file use tar.'], ['Which file type compresses best?', ['JPEG', 'Log text', 'MP4', '.zip'], 1, 'Text has lots of repetition.']],
  c: { t: 'Compress <code>data.csv</code> with gzip <b>keeping</b> the original file.', try: 'gzip -k data.csv', chk: ctx => has('data.csv.gz') && has('data.csv') },
});
lesson('zip', {
  n: 'zip', s: 'Creates .zip archives (compressed, one file holding many) — the format Windows and macOS open natively.',
  an: 'A filing box where each document is individually shrink-wrapped and there\'s an index card at the front — you can pull out one document without unwrapping the rest.',
  nm: '<b>zip</b> (as in “zip it up”).',
  sx: 'zip [-r] [OPTIONS] ARCHIVE.zip FILE...', p: [['zip', 'cmd', 'The command.', true], ['[-r]', 'opt', 'Recurse into directories (needed for folders!).', false], ['ARCHIVE.zip', 'arg', 'Archive to create or update (.zip added if missing).', true], ['FILE...', 'arg', 'What to add.', true]],
  ex1: 'zip -r docs.zip docs',
  sc: [['openat', 'creates docs.zip', 'openat(AT_FDCWD, "docs.zip", O_RDWR|O_CREAT, 0666) = 3'], ['read + deflate + write', 'compresses each file separately and writes a local header + data', 'write(3, "PK\\3\\4…", 85) = 85'], ['write (central directory)', 'at the end, writes the index of all entries', 'write(3, "PK\\1\\2…", 292) = 292']],
  ch: 'Creates or updates the .zip (existing entries with the same names are replaced). Originals are kept.', out: '<code>  adding: docs/report.txt (deflated 38%)</code> per file.', ec: '0 OK, 12 nothing to do, others for errors.',
  f: [['-r', '--recurse-paths', 'Include folder contents.', 'zip -r a.zip dir', true], ['-q', '--quiet', 'No output.', 'zip -qr a.zip dir', false], ['-e', '--encrypt', 'Password-protect (weak legacy crypto).', 'zip -e secret.zip f', false], ['-9', '', 'Best compression.', 'zip -9r a.zip dir', false], ['-x PAT', '', 'Exclude.', 'zip -r a.zip dir -x "*.log"', false], ['-u', '', 'Update only changed files.', 'zip -ur a.zip dir', false]],
  e: [['zip -r docs.zip docs', '  adding: docs/ (stored 0%)\n  adding: docs/readme.txt (deflated 68%)…', 'Zip a folder.'], ['zip docs2.zip docs', '  adding: docs/ (stored 0%)', 'Gotcha: without -r only the empty folder is stored!'], ['zip files.zip notes.txt fruits.txt', '', 'Specific files.'], ['unzip -l docs.zip', '', 'List contents.'], ['ls -l docs.zip', '', 'Check the size.']],
  u: `<p>zip compresses <b>each member separately</b> and keeps a <b>central directory</b> at the end, so programs can list or extract one file quickly. tar.gz compresses everything as one stream (usually smaller, but no random access).</p><p>Use zip to share with Windows/macOS users; use tar.gz on Linux because it preserves owners, permissions and symlinks better.</p>`,
  adv: `<p>Each entry: local file header (PK\\x03\\x04) + data (stored or deflated) + optional data descriptor; at the end the central directory (PK\\x01\\x02 per entry) and end-of-central-directory record (PK\\x05\\x06). Unix permissions go in the "external attributes" field. <code>zip -e</code> uses ZipCrypto, which is breakable — use 7z or gpg for real encryption.</p>`,
  mi: [['zip docs.zip docs', 'Only the directory entry is added, no files.', 'zip -r docs.zip docs'], ['zip -e with an important secret', 'ZipCrypto is weak.', 'gpg -c file   or   7z a -p archive.7z'], ['zip docs docs', 'Archive named docs.zip — confusing.', 'zip -r docs.zip docs']],
  safe: 'zip doesn\'t remove originals; it may replace entries inside an existing .zip of the same name.',
  r: [['unzip', 'Extract or list.'], ['tar', 'Linux-native, preserves permissions.'], ['gzip', 'Single files.']],
  cs: ['<code>zip -r out.zip dir</code> (remember -r!)', '<code>unzip -l out.zip</code> list', 'Each file compressed separately', 'Originals kept', 'Best for sharing with Windows/macOS'],
  q: [['What does zip a.zip dir (without -r) store?', ['Everything', 'Only the empty directory entry', 'Nothing', 'Only hidden files'], 1, '-r is needed for contents.'], ['Why can zip extract one file quickly?', ['It\'s smaller', 'Each member is compressed separately and indexed', 'It uses RAM', 'It doesn\'t'], 1, 'Central directory + per-file compression.'], ['Does zip delete the original files?', ['Yes', 'No', 'Only with -m', 'Both B and C'], 3, 'Not by default; -m moves files into the zip.']],
  c: { t: 'Create <code>docs.zip</code> containing the docs folder <b>with its files</b>.', try: 'zip -r docs.zip docs', chk: ctx => { const r = HP('docs.zip'); const z = r.n && unpack('ZIP', r.n.data); return z && z.entries.some(e => e.p.includes('report.txt')); } },
});
lesson('unzip', {
  n: 'unzip', s: 'Lists, tests and extracts .zip archives.',
  an: 'Opening the shrink-wrapped filing box and putting each document back on the shelf — or just reading the index card (-l).',
  nm: '<b>un</b>-<b>zip</b>.',
  sx: 'unzip [OPTIONS] ARCHIVE.zip [FILES...] [-d DIR]', p: [['unzip', 'cmd', 'The command.', true], ['[OPTIONS]', 'opt', '-l list, -t test, -o overwrite, -n never overwrite, -q quiet.', false], ['ARCHIVE.zip', 'arg', 'The archive.', true], ['[-d DIR]', 'arg', 'Extract into DIR (created if needed).', false]],
  ex1: 'unzip docs.zip -d restored',
  sc: [['openat + lseek(END)', 'opens the zip and seeks to the central directory at the end', 'lseek(3, -22, SEEK_END) = 312'], ['read', 'reads the index', 'read(3, "PK\\1\\2…", 292) = 292'], ['mkdir / openat / write', 'creates directories and files, inflating each entry', 'openat(AT_FDCWD, "restored/docs/report.txt", O_WRONLY|O_CREAT|O_TRUNC, 0644) = 4']],
  ch: 'Creates files (asks before overwriting unless -o / -n).', out: '<code>Archive: docs.zip</code> then <code>inflating: …</code> lines.', ec: '0 OK, 1 warnings, 9 not a zip, 11 no matching files.',
  f: [['-l', '', 'List contents.', 'unzip -l a.zip', true], ['-d DIR', '', 'Destination directory.', 'unzip a.zip -d out', true], ['-o', '', 'Overwrite without asking.', 'unzip -o a.zip', false], ['-n', '', 'Never overwrite.', 'unzip -n a.zip', false], ['-t', '', 'Test integrity.', 'unzip -t a.zip', false], ['-q', '', 'Quiet.', 'unzip -q a.zip', false]],
  e: [['unzip -l docs.zip', '  Length      Date    Time    Name\n…', 'Look before extracting.'], ['unzip docs.zip -d restored', 'Archive:  docs.zip\n   creating: docs/\n  inflating: docs/readme.txt…', 'Extract into a new folder.'], ['ls -R restored', '', 'Check the result.'], ['unzip -q docs.zip -d quiet', '', 'Silently.'], ['unzip missing.zip', 'unzip: cannot find or open missing.zip…', 'Error case.']],
  u: `<p>Always <b>list first</b> (<code>-l</code>): some archives contain a single top folder, others dump dozens of files into the current directory (“zip bomb” of clutter). Extract into a dedicated folder with <code>-d</code>.</p><p>“Zip slip”: malicious archives with paths like <code>../../.bashrc</code> try to write outside the target. unzip warns and strips ../ by default.</p>`,
  adv: `<p>unzip reads the End Of Central Directory record (last 22+ bytes), then each central-directory entry gives the offset of the local header. Per-entry CRC32 is verified on extraction. Unix modes are restored from external attributes when the archive was made on Unix.</p>`,
  mi: [['unzip a.zip in your home', 'Hundreds of files spill into ~.', 'unzip -l a.zip; unzip a.zip -d a/'], ['unzip a.tar.gz', 'Not a zip file (end-of-central-directory signature not found).', 'tar -xzf a.tar.gz'], ['Trusting unzip -o', 'Silently overwrites your files.', 'unzip -n, or extract to a new dir']],
  w: 'Extracting can <b>overwrite files</b> with the same names (with -o without asking). List first and extract into a fresh directory with <code>-d</code>; be wary of archives from untrusted sources.',
  r: [['zip', 'Create zip archives.'], ['tar', 'tar -xzf for .tar.gz.']],
  cs: ['<code>unzip -l a.zip</code> list first', '<code>unzip a.zip -d dir</code> extract into dir', '<code>-o</code> overwrite · <code>-n</code> never', '<code>-t</code> test integrity', '.tar.gz is NOT a zip → tar -xzf'],
  q: [['How do you see what\'s in a zip without extracting?', ['unzip -v', 'unzip -l', 'unzip -x', 'cat a.zip'], 1, '-l lists.'], ['Which option extracts into a specific folder?', ['-c', '-f', '-d', '-o'], 2, '-d DIR.'], ['unzip a.tar.gz fails because…', ['wrong permissions', 'it\'s a tar.gz, not a zip', 'too big', 'needs -r'], 1, 'Different format.']],
  c: { t: 'Extract <code>docs.zip</code> into a new folder called <code>restored</code> (create docs.zip first if needed).', try: 'unzip docs.zip -d restored', chk: ctx => has('restored/docs/report.txt') },
});
